UPDATE `quest_template_locale` SET `Details` = '棒极了！你在战歌峡谷保卫战中表现突出！愿你的英雄事迹在我们的土地上流传开来。', `VerifiedBuild` = 0 WHERE `locale` = 'zhCN' AND `ID` = 8428;
